<script lang="ts">
  import { onMount } from 'svelte';
  import type { GameMetadata } from '../data/games';
  import { readLocal, writeLocal } from '../lib/storage';
  let { games, base, guide }: { games: GameMetadata[]; base: string; guide: string } = $props();
  let query = $state(''); let genre = $state('All games'); let sort = $state('newest'); let compact = $state(false);
  const genres = $derived(['All games', ...new Set(games.map(game => game.genre))]);
  const filtered = $derived(games.filter(game => (genre === 'All games' || game.genre === genre) && `${game.title} ${game.description} ${game.tags.join(' ')}`.toLowerCase().includes(query.toLowerCase())).toSorted((a, b) => sort === 'title' ? a.title.localeCompare(b.title) : sort === 'oldest' ? a.date.localeCompare(b.date) : b.date.localeCompare(a.date)));
  onMount(() => { sort = readLocal('sort', 'newest', (value): value is string => ['newest', 'oldest', 'title'].includes(String(value))); compact = readLocal('compact', false, (value): value is boolean => typeof value === 'boolean'); });
  function multiplayerLabel(game: GameMetadata): string {
    const modes = game.multiplayer?.modes;
    if (!modes?.length) return 'Solo';
    return `${game.solo === false ? 'Multiplayer' : 'Solo + multiplayer'} · ${Math.min(...modes.map(mode => mode.minPlayers))}–${Math.max(...modes.map(mode => mode.maxPlayers))} players`;
  }
  function reset() { query = ''; genre = 'All games'; }
</script>

<section class="library pt-[28px] [border-top:1px_solid_var(--line)] max-[500px]:pt-[24px]" id="library" aria-labelledby="library-title">
  <div class="library-heading flex items-center justify-between mb-[27px] [&_.eyebrow]:text-[9px] [&_.eyebrow]:mb-[9px] max-[500px]:mb-[22px]"><div><p class="eyebrow font-sans text-[10px] font-semibold tracking-[1.8px] text-muted">THE COLLECTION</p><h2 id="library-title">Game library <span class="count inline-grid place-items-center font-sans text-[12px] [background:#272330] text-accent [border:1px_solid_#3a3148] min-w-[26px] h-[24px] rounded-[6px] [vertical-align:middle] ml-[8px]">{games.length}</span></h2></div><span class="library-note text-muted text-[11px] max-[760px]:hidden"><span class="status-dot inline-block w-[6px] h-[6px] bg-mint rounded-[50%] [vertical-align:middle] mr-[7px]"></span> No downloads. Just play.</span></div>
  <div class="toolbar flex gap-[10px] max-[500px]:flex-wrap"><label class="search flex items-center flex-1 [border:1px_solid_var(--line)] rounded-[7px] [background:#19181e] p-[0_14px] gap-[10px] [&>span]:text-[27px] [&>span]:text-[#928c9f] [&>span]:leading-[1] [&_input]:bg-transparent [&_input]:border-0 [&_input]:[outline-offset:0] [&_input]:min-w-[0] [&_input]:w-full [&_input]:p-[13px_0] [&_input]:text-[12px] [&_input::placeholder]:text-[#817b8c] [&_button]:border-0 [&_button]:bg-transparent [&_button]:text-[20px] max-[500px]:[flex-basis:100%]"><span aria-hidden="true">⌕</span><input type="search" aria-label="Search games" placeholder="Find your next favorite…" bind:value={query}/>{#if query}<button aria-label="Clear search" onclick={() => query = ''}>×</button>{/if}</label><label class="sort flex items-center [background:#19181e] [border:1px_solid_var(--line)] rounded-[7px] pl-[15px] text-[11px] gap-[6px] [&>span]:text-[#8f899c] [&_select]:border-0 [&_select]:bg-transparent [&_select]:p-[12px_24px_12px_3px] [&_select]:text-[11px] max-[500px]:flex-1 max-[500px]:justify-between max-[500px]:[&_select]:p-[12px_15px]"><span>Sort by</span><select aria-label="Sort games" bind:value={sort} onchange={(event) => writeLocal('sort', event.currentTarget.value)}><option value="newest">Newest first</option><option value="oldest">Oldest first</option><option value="title">Title A–Z</option></select></label><button class="view-button text-[22px] w-[45px] [background:#27232e] text-accent" aria-label={compact ? 'Use spacious grid' : 'Use compact grid'} aria-pressed={compact} onclick={() => { compact = !compact; writeLocal('compact', compact); }}>▦</button></div>
  <div class="filter-row flex justify-between items-center p-[17px_0_20px] max-[500px]:pb-[17px]"><div class="filters flex gap-[8px] flex-wrap [&_button]:text-[11px] [&_button]:p-[7px_12px] [&_button_span]:ml-[9px] [&_button_span]:text-[#a58dca] [&_button_span]:text-[10px]" aria-label="Filter by genre">{#each genres as item (item)}<button class={genre === item ? 'bg-[#2c253b] text-[#d2bdfb] border-[#453653]' : 'border-transparent bg-transparent text-muted'} aria-pressed={genre === item} onclick={() => genre = item}>{item}{#if item === 'All games'}<span>{games.length}</span>{/if}</button>{/each}</div><span class="results [font:10px_monospace] text-[#827b8e]" aria-live="polite">{filtered.length} {filtered.length === 1 ? 'game' : 'games'}</span></div>
  {#if games.length === 0}
    <div class="empty-state min-h-[403px] [border:1px_dashed_#37313f] rounded-[12px] flex flex-col items-center justify-center text-center p-[35px_20px] [background:radial-gradient(ellipse_at_50%_30%,#bba4fa06,transparent_60%),#16151b] [&_h3]:text-[26px] [&_h3]:font-medium [&_h3]:tracking-[-.6px] [&_h3]:leading-[1.25] [&_p]:text-[12px] [&_p]:text-muted [&_p]:m-[14px_0_23px] [&_p]:leading-[1.8] min-[1400px]:min-h-[430px] max-[500px]:p-[32px_16px] max-[500px]:min-h-[405px] max-[500px]:[&_h3]:text-[24px] max-[500px]:[&_p]:text-[12px]"><div class="empty-icon relative w-[72px] mb-[20px] text-[#a18bbd] [&_svg]:w-[65px] [&_svg]:h-[55px]" aria-hidden="true"><svg viewBox="0 0 80 64" fill="none"><path d="M20 17h40l10 31c2 8-7 12-12 7l-9-8H31l-9 8c-5 5-14 1-12-7z" stroke="currentColor" stroke-width="2"/><path d="M27 27v14M20 34h14" stroke="currentColor" stroke-width="2"/><circle cx="52" cy="30" r="2" fill="currentColor"/><circle cx="59" cy="37" r="2" fill="currentColor"/><path d="M35 17V8h10V2" stroke="currentColor" stroke-width="2"/></svg><span class="mini-spark absolute right-[-7px] top-[-3px] text-[17px] text-mint">✧</span></div><span class="empty-tag text-[#8c7f9d] [font:8px_monospace] tracking-[1.5px] mb-[12px]">AN EMPTY LIBRARY. A FRESH START.</span><h3>The next great little game<br/>could be yours.</h3><p>No games here just yet. This space is ready for whatever<br class="desktop-break max-[500px]:hidden"/> you dream up, build, and hit publish on.</p><a class="button primary inline-flex items-center justify-center gap-[24px] p-[12px_18px] rounded-[6px] text-[12px] font-semibold [border:1px_solid_transparent] bg-accent text-[#21182f] [&:hover]:[background:#cbb7ff]" href={guide}>Add your first game <span aria-hidden="true">↗</span></a><span class="empty-footnote text-[9px] text-[#807889] mt-[14px]">One idea. One folder. A new place to play.</span></div>
  {:else if filtered.length === 0}
    <div class="empty-state min-h-[403px] [border:1px_dashed_#37313f] rounded-[12px] flex flex-col items-center justify-center text-center p-[35px_20px] [background:radial-gradient(ellipse_at_50%_30%,#bba4fa06,transparent_60%),#16151b] [&_h3]:text-[26px] [&_h3]:font-medium [&_h3]:tracking-[-.6px] [&_h3]:leading-[1.25] [&_p]:text-[12px] [&_p]:text-muted [&_p]:m-[14px_0_23px] [&_p]:leading-[1.8] min-[1400px]:min-h-[430px] max-[500px]:p-[32px_16px] max-[500px]:min-h-[405px] max-[500px]:[&_h3]:text-[24px] max-[500px]:[&_p]:text-[12px]"><h3>No games found.</h3><p>Try a different search or genre.</p><button class="button primary inline-flex items-center justify-center gap-[24px] p-[12px_18px] rounded-[6px] text-[12px] font-semibold [border:1px_solid_transparent] bg-accent text-[#21182f] [&:hover]:[background:#cbb7ff]" onclick={reset}>Clear filters</button></div>
  {:else}
    <div class={['grid gap-[22px] max-[760px]:grid-cols-2 max-[500px]:grid-cols-1', compact ? 'grid-cols-4' : 'grid-cols-3']}>{#each filtered as game (game.id)}<a class="game-card flex flex-col [border:1px_solid_var(--line)] rounded-[9px] overflow-hidden bg-surface [transition:transform_.15s,border-color_.15s] [&:hover]:[transform:translateY(-3px)] [&:hover]:[border-color:#78638f]" href={`${base}play/${game.id}/`}><div class="game-cover [aspect-ratio:16/10] [background:#30283e] grid place-items-center relative overflow-hidden text-[50px] text-accent [&_img]:absolute [&_img]:inset-0 [&_img]:w-full [&_img]:h-full [&_img]:object-cover">{#if game.cover}<img src={`${base}games/${game.id}/${game.cover}`} alt="" loading="lazy"/>{:else}<span aria-hidden="true">▧</span>{/if}<span class="play-chip absolute bottom-[12px] right-[12px] text-[11px] [background:#17131ee6] p-[7px_10px] rounded-[5px]">Play ↗</span></div><div class="card-copy flex flex-1 flex-col p-[19px] [&_h3]:text-[20px] [&_h3]:m-[7px_0] [&_p]:text-[12px] [&_p]:text-muted [&_p]:[display:-webkit-box] [&_p]:[-webkit-line-clamp:2] [&_p]:[-webkit-box-orient:vertical] [&_p]:overflow-hidden"><span class="eyebrow font-sans text-[10px] font-semibold tracking-[1.8px] text-muted">{game.genre}</span><h3>{game.title}</h3><p>{game.description}</p><span class="flex items-center gap-[7px] text-[10px] text-mint mt-[12px]">{#if game.multiplayer}<svg class="shrink-0" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>{/if}{multiplayerLabel(game)}</span><span class="card-author block text-[10px] text-[#8f849f] mt-auto [padding-top:19px]">By {game.author}</span></div></a>{/each}</div>
  {/if}
</section>
